<?php
namespace App\Controllers;
use App\Core\{Auth,View,Database,Request,Csrf,Response};
final class CalendarController {
 public function index():void{Auth::requireLogin();$users=Database::pdo()->query("SELECT id,full_name FROM users WHERE is_active=1 AND is_banned=0 ORDER BY full_name")->fetchAll();View::render('calendar/index',['users'=>$users]);}
 public function day():never{Auth::requireLogin();$date=$_GET['date']??date('Y-m-d');$s=Database::pdo()->query('SELECT r.*,u.full_name assigned_name,GROUP_CONCAT(c.full_name SEPARATOR ", ") clients FROM reminders r LEFT JOIN users u ON u.id=r.assigned_user_id LEFT JOIN reminder_clients rc ON rc.reminder_id=r.id LEFT JOIN clients c ON c.id=rc.client_id WHERE r.status=\'active\' GROUP BY r.id ORDER BY r.reminder_at');$rows=[];$target=new \DateTimeImmutable($date);foreach($s->fetchAll() as $r){$start=new \DateTimeImmutable($r['reminder_at']);$end=$r['recurrence_end_date']?new \DateTimeImmutable($r['recurrence_end_date']):null;$match=false;$type=$r['recurrence_type']??'none';if($type==='none')$match=$start->format('Y-m-d')===$date;else if($target>=$start&&(!$end||$target->format('Y-m-d')<=$end->format('Y-m-d'))){$interval=max(1,(int)$r['recurrence_interval']);$days=(int)$target->diff($start)->format('%a');if($type==='daily')$match=$days%$interval===0;elseif($type==='weekly')$match=(int)floor($days/7)%$interval===0 && $target->format('N')===$start->format('N');elseif($type==='monthly')$match=$target->format('d')===$start->format('d') && (((int)$target->format('Y')*12+(int)$target->format('m'))-((int)$start->format('Y')*12+(int)$start->format('m')))%$interval===0;elseif($type==='custom')$match=$days%$interval===0;}if($match){$r['occurrence_date']=$date;$rows[]=$r;}}Response::json(['data'=>$rows]);}
 public function clients():never{Auth::requireLogin();$q=trim($_GET['q']??'');$s=Database::pdo()->prepare('SELECT id,client_no,full_name,email,phone FROM clients WHERE deleted_at IS NULL AND full_name LIKE ? ORDER BY full_name LIMIT 30');$s->execute(['%'.$q.'%']);Response::json(['data'=>$s->fetchAll()]);}
 public function store():never{$this->save(null);}
 public function update($id):never{$this->save((int)$id);}
 private function save(?int $id):never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){Response::json(['error'=>'CSRF'],419);} $pdo=Database::pdo();$fields=['title','description','reminder_at','reminder_type','assigned_user_id','recurrence_type','recurrence_interval','recurrence_unit','recurrence_end_date'];$values=[$r->input('title'),$r->input('description'),$r->input('reminder_at'),$r->input('reminder_type','general'),$r->input('assigned_user_id')?:Auth::id(),$r->input('recurrence_type','none'),max(1,(int)$r->input('recurrence_interval',1)),$r->input('recurrence_unit','days')?:'days',$r->input('recurrence_end_date')?:null];$pdo->beginTransaction();try{if($id){$set=implode(',',array_map(fn($f)=>$f.'=?',$fields));$pdo->prepare("UPDATE reminders SET $set,updated_at=NOW() WHERE id=?")->execute([...$values,$id]);$pdo->prepare('DELETE FROM reminder_clients WHERE reminder_id=?')->execute([$id]);}else{$pdo->prepare('INSERT INTO reminders(tenant_id,title,description,reminder_at,reminder_type,status,assigned_user_id,created_by,recurrence_type,recurrence_interval,recurrence_unit,recurrence_end_date,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?, ?,?,?,?,NOW(),NOW())')->execute([$values[0],$values[1],$values[2],$values[3],'active',$values[4],Auth::id(),$values[5],$values[6],$values[7],$values[8]]);$id=(int)$pdo->lastInsertId();}$ins=$pdo->prepare('INSERT INTO reminder_clients(reminder_id,client_id) VALUES(?,?)');foreach((array)$r->input('client_ids',[]) as $cid)if((int)$cid>0)$ins->execute([$id,(int)$cid]);$pdo->commit();Response::json(['success'=>true,'id'=>$id]);}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();Response::json(['error'=>$e->getMessage()],500);}}
 public function delete($id):never{Auth::requireLogin();Database::pdo()->prepare("UPDATE reminders SET status='cancelled',updated_at=NOW() WHERE id=?")->execute([(int)$id]);Response::json(['success'=>true]);}
}
